    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from math import comb, gcd
# pick an odd m >= 7 from a set that ensures nontrivial trig sum
m = rng.choice([7, 9, 11, 13])
# choose p >= 3
p = rng.randint(3, 7)
# choose distinct positive integer lambdas
vals = list(range(2, 10))
rng.shuffle(vals)
lambda1, lambda2, lambda3 = vals[0], vals[1], vals[2]
# compute gcd of binomial(m,k) for k = 1..(m-1)/2
g = 0
for k in range(1, (m-1)//2 + 1):
    b = comb(m, k)
    g = b if g == 0 else gcd(g, b)
# pick L as a divisor of g (prefer >1 to make constants nontrivial)
divisors = [d for d in range(1, g+1) if g % d == 0]
if len(divisors) > 1:
    # bias towards choosing a nontrivial L when possible
    nontrivial = [d for d in divisors if d > 1]
    if nontrivial and rng.random() < 0.7:
        L = rng.choice(nontrivial)
    else:
        L = rng.choice(divisors)
else:
    L = divisors[0]
# compute mu's as reduced fractions: mu1 = (((p-1)*lambda1) + lambda3)/p, etc.
def frac_str(num, den):
    g2 = gcd(num, den)
    num //= g2
    den //= g2
    if den == 1:
        return f"{num}"
    return f"{num}/{den}"
mu1_num = (p-1)*lambda1 + lambda3
mu2_num = (p-1)*lambda2 + lambda1
mu3_num = (p-1)*lambda3 + lambda2
mu1 = frac_str(mu1_num, p)
mu2 = frac_str(mu2_num, p)
mu3 = frac_str(mu3_num, p)
return {
    'm': m,
    'p': p,
    'L': L,
    'lambda1': lambda1,
    'lambda2': lambda2,
    'lambda3': lambda3,
    'mu1': mu1,
    'mu2': mu2,
    'mu3': mu3
}

